CREATE TABLE experiment_case (id BIGSERIAL PRIMARY KEY, experiment_id VARCHAR(40) NOT NULL UNIQUE, name TEXT NOT NULL, stage VARCHAR(24) NOT NULL, status VARCHAR(24) NOT NULL DEFAULT 'active', final_profit_status VARCHAR(24) NOT NULL DEFAULT 'pending', final_revenue NUMERIC(18,4) NOT NULL DEFAULT 0, final_total_cost NUMERIC(18,4) NOT NULL DEFAULT 0, final_profit_amount NUMERIC(18,4) NOT NULL DEFAULT 0, profit_currency VARCHAR(8) NOT NULL DEFAULT '', cash_recovery_status VARCHAR(24) NOT NULL DEFAULT 'pending', cash_recovered_amount NUMERIC(18,4) NOT NULL DEFAULT 0, cash_currency VARCHAR(8) NOT NULL DEFAULT '', cash_recovered_at TIMESTAMPTZ, final_decision VARCHAR(16) NOT NULL DEFAULT '', owner_id BIGINT NOT NULL DEFAULT 0, created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(), updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW());
CREATE TABLE experiment_gate_decision (id BIGSERIAL PRIMARY KEY, experiment_id VARCHAR(40) NOT NULL REFERENCES experiment_case(experiment_id) ON DELETE CASCADE, stage VARCHAR(24) NOT NULL, gate_code VARCHAR(80) NOT NULL, result VARCHAR(16) NOT NULL, reason TEXT NOT NULL DEFAULT '', evidence_ids TEXT NOT NULL DEFAULT '[]', decided_by BIGINT NOT NULL DEFAULT 0, created_at TIMESTAMPTZ NOT NULL DEFAULT NOW());
CREATE INDEX idx_experiment_gate_experiment ON experiment_gate_decision(experiment_id);
CREATE TABLE experiment_evidence (id BIGSERIAL PRIMARY KEY, experiment_id VARCHAR(40) NOT NULL REFERENCES experiment_case(experiment_id) ON DELETE CASCADE, stage VARCHAR(24) NOT NULL, evidence_kind VARCHAR(16) NOT NULL DEFAULT 'support', truth_status VARCHAR(16) NOT NULL, title TEXT NOT NULL, source_uri TEXT NOT NULL DEFAULT '', observed_at TIMESTAMPTZ, expires_at TIMESTAMPTZ, verified_by BIGINT NOT NULL DEFAULT 0, verified_at TIMESTAMPTZ, created_at TIMESTAMPTZ NOT NULL DEFAULT NOW());
CREATE INDEX idx_experiment_evidence_experiment ON experiment_evidence(experiment_id);
CREATE TABLE experiment_object_link (id BIGSERIAL PRIMARY KEY, experiment_id VARCHAR(40) NOT NULL REFERENCES experiment_case(experiment_id) ON DELETE CASCADE, object_type VARCHAR(40) NOT NULL, object_id VARCHAR(80) NOT NULL, created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(), UNIQUE(experiment_id, object_type, object_id));
